import { ChatComposer } from "@aevryn/ui/components/chat-composer";
import { createServerSupabaseForNext } from "@/lib/supabase-server";

export default function WorkspacePage({
  params,
}: {
  params: Promise<{ workspaceId: string; threadId?: string }>;
}) {
  const supabase = createServerSupabaseForNext();

  useEffect(() => {
    async function fetchNavSections() {
      const { data, error } = await supabase
        .from("groups")
        .select("*")
        .eq("workspace_id", params.workspaceId);

      if (error) console.error("Error fetching groups:", error);
      // TODO: map groups to NavSection items
