import { getBrowserSupabase } from "@/lib/supabase-client";

export default function WorkspacePage({
  params,
}: {
  params: Promise<{ workspaceId: string; threadId?: string }>;
}) {
  const [navSections, setNavSections] = useState<import("@aevryn/ui/components/sidebar-preset/nav-data").NavSection[]>([]);
  const supabase = getBrowserSupabase();

  useEffect(() => {
    async function fetchNavSections() {
      const resolved = await params;
      const { data, error } = await supabase
        .from("groups")
        .select("*")
        .eq("workspace_id", resolved.workspaceId);

      if (error) console.error("Error fetching groups:", error);

      if (data && data.length > 0) {
        const sections = data.map((group) => ({
          label: group.name,
          items: [],
        }));
        setNavSections(sections);
      }
    }

    fetchNavSections();
  }, [params]);

  return (
    <div className="flex-1 min-h-[400px] flex items-center justify-center">
      <ChatComposer />
    </div>
  );
}

